    def longestPalindrome(self, n: int, edges: List[List[int]], labels: str) -> int:
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited_states = set()
        queue = deque()
        max_len = 1

