public:
    int longestPalindrome(int n, std::vector<std::vector<int>>& edges, std::string labels) {
        std::vector<std::vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        std::unordered_set<std::tuple<int, int, int>, StateHash> visited;
        std::queue<std::tuple<int, int, int, int>> qu;
        int max_len = 1;

        for (int i = 0; i < n; ++i) {
            int mask = (1 << i);
            visited.insert({mask, i, i});
            qu.push({mask, i, i, 1});
        }

        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            if (labels[u] == labels[v]) {
                int mask = (1 << u) | (1 << v);
                visited.insert({mask, u, v});
                visited.insert({mask, v, u});
                qu.push({mask, u, v, 2});
                qu.push({mask, v, u, 2});
                max_len = std::max(max_len, 2);
            }
        }

        while (!qu.empty()) {
            auto [mask, u, v, len] = qu.front();
            qu.pop();
            max_len = std::max(max_len, len);

            for (int nu : adj[u]) {
                if (mask & (1 << nu)) continue;
                for (int nv : adj[v]) {
                    if (nu == nv || (mask & (1 << nv))) continue;
                    if (labels[nu] == labels[nv]) {
                        int new_mask = mask | (1 << nu) | (1 << nv);
                        if (visited.insert({new_mask, nu, nv}).second) {
                            qu.push({new_mask, nu, nv, len + 2});
                        }
                    }
                }
            }
        }

        return max_len;
    }
