import java.util.*;

class Solution {
    public int longestPalindrome(int n, int[][] edges, String labels) {
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        Set<Long> visited = new HashSet<>();
        Queue<int[]> queue = new ArrayDeque<>();
        int maxLen = 1;

        for (int i = 0; i < n; i++) {
            int mask = (1 << i);
            long state = ((long) mask << 16) | (i << 8) | i;
            visited.add(state);
            queue.add(new int[]{mask, i, i, 1});
        }

        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (labels.charAt(u) == labels.charAt(v)) {
                int mask = (1 << u) | (1 << v);
                visited.add(((long) mask << 16) | (u << 8) | v);
                visited.add(((long) mask << 16) | (v << 8) | u);
                queue.add(new int[]{mask, u, v, 2});
                queue.add(new int[]{mask, v, u, 2});
                maxLen = Math.max(maxLen, 2);
            }
        }

        while (!queue.isEmpty()) {
            int[] top = queue.poll();
            int mask = top[0], u = top[1], v = top[2], len = top[3];
            maxLen = Math.max(maxLen, len);

            for (int nu : adj.get(u)) {
                if ((mask & (1 << nu)) != 0) continue;
                for (int nv : adj.get(v)) {
                    if (nu == nv || (mask & (1 << nv)) != 0) continue;
                    if (labels.charAt(nu) == labels.charAt(nv)) {
                        int newMask = mask | (1 << nu) | (1 << nv);
                        long nextState = ((long) newMask << 16) | (nu << 8) | nv;
                        if (visited.add(nextState)) {
                            queue.add(new int[]{newMask, nu, nv, len + 2});
                        }
                    }
                }
            }
        }

        return maxLen;
    }
}

