var longestPalindrome = function(n, edges, labels) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const visited = new Set();
    const queue = [];
    let maxLen = 1;

    for (let i = 0; i < n; i++) {
        const mask = (1 << i);
        visited.add(`${mask},${i},${i}`);
        queue.push([mask, i, i, 1]);
    }

    for (const [u, v] of edges) {
        if (labels[u] === labels[v]) {
            const mask = (1 << u) | (1 << v);
            visited.add(`${mask},${u},${v}`);
            visited.add(`${mask},${v},${u}`);
            queue.push([mask, u, v, 2]);
            queue.push([mask, v, u, 2]);
            if (maxLen < 2) maxLen = 2;
        }
    }

    let head = 0;
    while (head < queue.length) {
        const [mask, u, v, len] = queue[head++];
        if (len > maxLen) maxLen = len;

        for (const nu of adj[u]) {
            if (mask & (1 << nu)) continue;
            for (const nv of adj[v]) {
                if (nu === nv || (mask & (1 << nv))) continue;
                if (labels[nu] === labels[nv]) {
                    const newMask = mask | (1 << nu) | (1 << nv);
                    const key = `${newMask},${nu},${nv}`;
                    if (!visited.has(key)) {
                        visited.add(key);
                        queue.push([newMask, nu, nv, len + 2]);
                    }
                }
            }
        }
    }

    return maxLen;
};
